def find_connected_components(edges):
    parent = {}

    def find(x):
        if x not in parent:
            parent[x] = x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        parent[ra] = rb

    for edge in edges:
        union(edge[0], edge[1])

    components = {}
    for node in parent:
        root = find(node)
        if root not in components:
            components[root] = set()
        components[root].add(node)

    return list(components.values())
```

