    lvl = 0

    # Use `set` to eliminate the redundancy of remainders within the same level.
    que = {n}
    while que:
        next_que = set()
        lvl += 1
        for remain in que:
            for sq in square_nums:
                if remain == sq:
                    return lvl
                elif remain >= sq:
