class Solution(object):
    def findMaximumXOR(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        res, mask = 0, 0
        for i in range(31, -1, -1):
            mask |= (1 << i)
            tmpSet = set()
            for n in nums:
                tmpSet.add(n & mask)
            tmpRes = res | (1 << i)
            for pre in tmpSet:
                if tmpRes ^ pre in tmpSet:
                    res = tmpRes
                    break
        return res

def max_xor(nums):
    solution = Solution()
    return solution.findMaximumXOR(nums)
