# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def is_symmetric(root: Optional[TreeNode]) -> bool:
    if not root:
        return True

    def check(left, right):
        if not left and not right:
            return True
        if not left or not right:
            return False
        return left.val == right.val and check(left.left, right.right) and check(left.right, right.left)

    return check(root.left, root.right)

def construct(arr):
    if not arr:
        return None
    root = TreeNode(arr.pop(0))
    queue = deque([root])
    while arr:
        node = queue.popleft()
        if arr:
            val = arr.pop(0)
            left = TreeNode(val) if val is not None else None
            node.left = left
            if left:
                queue.append(left)
        if arr:
            val = arr.pop(0)
            right = TreeNode(val) if val is not None else None
            node.right = right
            if right:
                queue.append(right)
    return root

assert is_symmetric(construct([1,2,2,3,4,4,3]))==True
assert is_symmetric(construct([1,2,2,None,3,None,3]))==False
assert is_symmetric(construct([1]))==True
