def max_xor(nums):
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.isEnd = False

    class Trie:
        def __init__(self):
            self.root = TrieNode()

        def insert(self, num):
            node = self.root
            for i in range(31, -1, -1):
                bit = (num >> i) & 1
                if bit not in node.children:
                    node.children[bit] = TrieNode()
                node = node.children[bit]
            node.isEnd = True

        def max_xor_helper(self, num):
            node = self.root
            xor = 0
            for i in range(31, -1, -1):
                bit = (num >> i) & 1
                toggle = 1 - bit
                if toggle in node.children:
                    xor |= (1 << i)
                    node = node.children[toggle]
                else:
                    node = node.children[bit]
            return xor

    trie = Trie()
    max_xor = 0
    for num in nums:
        trie.insert(num)
        max_xor = max(max_xor, trie.max_xor_helper(num))

    return max_xor
