def length_of_longest_substring_k_distinct(s, k):
    """
    :type s: str
    :type k: int
    :rtype: int
    """
    ans = 0

    if not s or not k or k < 0:
        return ans

    freqs = {}
    i = cnt = 0

    for j in range(len(s)):
        if s[j] in freqs:
            freqs[s[j]] += 1
        else:
            freqs[s[j]] = 1
            cnt += 1

        while cnt > k:
            if freqs[s[i]] == 1:
                del freqs[s[i]]
                cnt -= 1
            else:
                freqs[s[i]] -= 1

            i += 1

        ans = max(ans, j - i + 1)

    return ans
