def min_jumps(arr):
    n = len(arr)
    if n <= 1:
        return 0
    if arr[0] == 0:
        return -1

    max_reach = arr[0]
    step = arr[0]
    jump = 1

    if n == 1:
        return 0

    for i in range(1, n):
        if i == n - 1:
            return jump

        max_reach = max(max_reach, i + arr[i])

        step -= 1

        if step == 0:
            jump += 1

            if i >= max_reach:
                return -1

            if max_reach >= n - 1:
                return jump

            step = max_reach - i

    return -1
