from collections import defaultdict, deque

def min_jumps(arr):
    maps = defaultdict(list)
    for i, num in enumerate(arr):
        maps[num].append(i)

    queue = deque([0])
    visited = {0}
    rank = 0
    while queue:
        n = len(queue)
        for _ in range(n):
            node = queue.popleft()
            if node == len(arr) - 1:
                return rank
            children = maps[arr[node]]
            for child in children:
                if child not in visited:
                    visited.add(child)
                    queue.append(child)
            maps[arr[node]].clear()
            if node + 1 not in visited and node + 1 < len(arr):
                visited.add(node + 1)
                queue.append(node + 1)
            if node - 1 not in visited and node - 1 >= 0:
                visited.add(node - 1)
                queue.append(node - 1)
        rank += 1
