def find_median(nums):
    low, high = [], []
    for num in nums:
        if len(low) == 0 or num < -low[0]:
            heappush(low, -num)
        else:
            heappush(high, num)

        if len(low) > len(high) + 1:
            heappush(high, -heappop(low))
        elif len(high) > len(low):
            heappush(low, -heappop(high))

