class TrieNode:
    def __init__(self):
        self.children = {}
        self.word = ''

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def addWord(self, word):
        node = self.root
        for char in word:
            if char in node.children:
                node = node.children[char]
            else:
                new_node = TrieNode()
                node.children[char] = new_node
                node = new_node
        node.word = word

    def is_valid_word(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
            if node.word == '':
                return False
        return True

def is_valid_word(dictionary, word):
    trie = Trie()
    for w in dictionary:
        trie.addWord(w)
    return trie.is_valid_word(word)
```

