from collections import deque
def sliding_window(nums, k):
    if not nums:
        return []
    if k == 1:
        return nums
    if k == len(nums):
        return [max(nums)]
    result = []
    queue = deque()
    for i in range(len(nums)):
        while queue and nums[queue[-1]] <= nums[i]:
            queue.pop()
        queue.append(i)
        if queue[0] == i - k:
            queue.popleft()
        if i >= k - 1:
            result.append(nums[queue[0]])
    return result
```

