    right = len(nums) - 1
    closest = float('inf')
    closest_val = nums[0]

    while left <= right:
        mid = (left + right) // 2
        if abs(target - nums[mid]) < closest:
            closest = abs(target - nums[mid])
            closest_val = nums[mid]
        elif abs(target - nums[mid]) == closest:
