def count_occurrences(A, x):
    def find_leftmost():
        left, right = 0, len(A) - 1
        while left < right:
            mid = left + (right - left) // 2
            if A[mid] < x:
                left = mid + 1
            else:
                right = mid
        return left if A[left] == x else -1

    def find_rightmost():
        left, right = 0, len(A) - 1
        while left < right:
            mid = left + (right - left + 1) // 2
            if A[mid] > x:
                right = mid - 1
            else:
                left = mid
        return left if A[left] == x else -1

    leftmost = find_leftmost()
    if leftmost == -1:
        return 0
    rightmost = find_rightmost()
    return rightmost - leftmost + 1
