    for i in range(len(graph)):
        if color[i] != 0: continue
        q = deque()
        q.append(i)
        color[i] = 1
        while q:
            cur = q.popleft()
            for e in graph[cur]:
                if color[e] != 0:
                    if color[cur] == color[e]:
