def max_subarray(arr, k):
    n = len(arr)
    if n < k:
        raise ValueError("Array length should be greater than or equal to k")

    max_in_subarray = []
    q = deque()

    for i in range(k):
        while q and arr[i] >= arr[q[-1]]:
            q.pop()
        q.append(i)

    for i in range(k, n):
        max_in_subarray.append(arr[q[0]])

        while q and q[0] <= i-k:
            q.popleft()

        while q and arr[i] >= arr[q[-1]]:
            q.pop()
        q.append(i)

    max_in_subarray.append(arr[q[0]])
    return max_in_subarray
