def binary_search_count(arr, target):
    def binary_search(arr, target, find_first):
        low, high = 0, len(arr) - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                result = mid
                if find_first:
                    high = mid - 1
                else:
                    low = mid + 1
            elif arr[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return result
    first = binary_search(arr, target, True)
    last = binary_search(arr, target, False)
    if first == -1 or last == -1:
        return 0
    return last - first + 1
