        return False
    return all(visited)

def dfs(node, parent, neighbors, visited):
    if visited[node]:
        return False
    visited[node] = True
    for neighbor in neighbors[node]:
        if neighbor != parent:
            if not dfs(neighbor, node, neighbors, visited):
                return False
    return True
