def next_closest_palindrome(n: str) -> str:
    length = len(n)
    mid = length // 2
    if n == n[::-1]:
        if re.match('^10*1$', n):
            return str(int(n) - 2)
        if re.match('^9+$', n):
            return str(int(n) + 2)
        if length & 1:
            s1 = str(int(n[:mid+1]) + 1)
            s2 = str(int(n[:mid+1]) - 1)
            si1 = int(s1[:-1] + s1[::-1])
            si2 = int(s2[:-1] + s2[::-1])
        else:
            s1 = str(int(n[:mid]) + 1)
            s2 = str(int(n[:mid]) - 1)
            si1 = int(s1 + s1[::-1])
            si2 = int(s2 + s2[::-1])
        return str([si2, si1][abs(si1 - int(n)) < abs(si2 - int(n))])
    else:
        ret = [int(e) for e in n]
        if length & 1:
            i, j = mid - 1, mid + 1
        else:
            i, j = mid - 1, mid
        dis = abs(ret[i] - ret[j])
        if length & 1:
            if dis <= 5:
                ret[j] = ret[i]
            else:
                if ret[j] > ret[i]:
                    ret[mid] += 1
                    if ret[mid] == 10:
                        ret[mid] = 0
                        ret[i] += 1
                else:
                    ret[mid] -= 1
                    if ret[mid] == -1:
                        ret[mid] = 9
                        ret[i] -= 1
                ret[j] = ret[i]
            for k in range(1, mid):
                x, y = i - k, j + k
                if ret[x] != ret[y]: ret[y] = ret[x]
        else:
            ret2 = ret[:]
            if ret[j] > ret[i]:
                ret[i] += 1
            else:
                ret[i] = (ret[i] - 1 + 10) % 10
            ret[j], ret2[j] = ret[i], ret2[i]
            for k in range(1, mid):
                x, y = i - k, j + k
                if ret[x] != ret[y]: ret[y] = ret[x]
                if ret2[x] != ret2[y]: ret2[y] = ret2[x]
            f = lambda x, y: x * 10 + y
            r1, r2 = reduce(f, ret), reduce(f, ret2)
            if abs(r1 - int(n)) == abs(r2 - int(n)):
                ret = ret2 if r2 < r1 else ret
            else:
                ret = [ret, ret2][abs(r1 - int(n)) > abs(r2 - int(n))]
        return ''.join([str(e) for e in ret])
