def shortest_distance(grid):
    def bfs(i, j):
        visited = {(i, j)}
        buildings = set()
        q = deque([(i, j, 0)])
        total_step = 0

        while q:
            i, j, step = q.popleft()
            if grid[i][j] == 1 and (i, j) not in buildings:
                total_step += step
                buildings.add((i, j))
            if len(buildings) == num_buildings:
                return total_step
            if grid[i][j] == 0:
                for x, y in ((i-1, j), (i+1, j), (i, j-1), (i, j+1)):
                    if 0 <= x < m and 0 <= y < n and (x, y) not in visited and grid[x][y] != 2:
                        q.append((x, y, step + 1))
                        visited.add((x, y))
        return float('inf')

    m, n = len(grid), len(grid[0])
    num_buildings = sum(grid[i][j] == 1 for i in range(m) for j in range(n))
    min_step = float('inf')

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                total_step = bfs(i, j)
                if min_step > total_step:
                    min_step = total_step

    return min_step if min_step != float('inf') else -1
