class TrieNode:
    def __init__(self):
        self.children = {}

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, val):
        node = self.root
        for shift in range(31, -1, -1):
            bit = (val >> shift) & 1
            if bit not in node.children:
                node.children[bit] = TrieNode()
            node = node.children[bit]

    def getMaxXor(self, val):
        node = self.root
        max_xor = 0
        for shift in range(31, -1, -1):
            bit = (val >> shift) & 1
            toggle_bit = 1 - bit
            if toggle_bit in node.children:
                max_xor |= (1 << shift)
                node = node.children[toggle_bit]
            else:
                node = node.children[bit]
        return max_xor

def find_Max_XOR(nums):
    trie = Trie()
    max_xor = float('-inf')
    for num in nums:
        trie.insert(num)
        max_xor = max(max_xor, trie.getMaxXor(num))
    return max_xor

