def is_valid_number(s):
    """
    :type s: str
    :rtype: bool
    """
    # remove leading and trailing spaces
    s = s.strip()

    # check for empty string
    if not s:
        return False

    # check for plus or minus sign
    if s[0] in ['+', '-']:
        s = s[1:]

    # check for decimal point
    dot_count = s.count('.')
    if dot_count > 1:
        return False

    # check for scientific notation
    e_count = s.count('e') + s.count('E')
    if e_count > 1:
        return False
    if 'e' in s or 'E' in s:
        parts = s.split('e') if 'e' in s else s.split('E')
        if len(parts) != 2:
            return False
        base, exponent = parts
        if not base or not exponent:
            return False
        if base[-1] == '.':
            return False
        if not base[-1].isdigit() and base[-1] != '.':
            return False
        if not exponent[0].isdigit() and exponent[0] != '+' and exponent[0] != '-':
            return False
        if not exponent[-1].isdigit():
            return False
        base = base.replace('.', '')
        if not base.isdigit():
            return False
        return True

    # check for valid decimal or integer
    if dot_count == 0:
        return s.isdigit()
    else:
        parts = s.split('.')
        if len(parts) != 2:
            return False
        left, right = parts
        if not left and not right:
            return False
        if not left.isdigit() and left:
            return False
        if not right.isdigit():
            return False
        return True
```

