def smallest_window(s: str) -> str:
    distinct_chars = len(set(s))
    count = {}
    start, min_len = 0, float('inf')
    min_start = 0
    distinct_count = 0

    for end in range(len(s)):
        if s[end] in count:
            count[s[end]] += 1
        else:
            count[s[end]] = 1

        if count[s[end]] == 1:
            distinct_count += 1

        while distinct_count == distinct_chars:
            if end - start + 1 < min_len:
                min_len = end - start + 1
                min_start = start

            count[s[start]] -= 1
            if count[s[start]] == 0:
                distinct_count -= 1
            start += 1

