    node = root
    xor_sum = 0
    for i in range(31, -1, -1):
        bit = (num >> i) & 1
        xor_bit = 1 - bit
        if xor_bit in node.children:
            node = node.children[xor_bit]
        else:
            node = node.children[bit]
        xor_sum = xor_sum * 2 + (1 - bit) * bit
    return xor_sum + (node.max_xor ^ num)

