def evaluate_expression(expression):
    expression = expression.replace(' ', '')
    tokens = []
    num = ''
    for char in expression:
        if char.isdigit():
            num += char
        else:
            tokens.append(int(num))
            tokens.append(char)
            num = ''
    tokens.append(int(num))

    i = 0
    while '*' in tokens or '/' in tokens:
        if tokens[i] == '*':
            tokens[i-1] = tokens[i-1] * tokens[i+1]
            del tokens[i:i+2]
        elif tokens[i] == '/':
            tokens[i-1] = tokens[i-1] // tokens[i+1]
            del tokens[i:i+2]
        else:
            i += 1
        if i == len(tokens):
            i = 0
    result = tokens[0]
    for i in range(1, len(tokens), 2):
        if tokens[i] == '+':
            result += tokens[i+1]
        else:
            result -= tokens[i+1]
    return result
