def has_cycle(edges):
    graph = {}
    for edge in edges:
        if edge[0] not in graph:
            graph[edge[0]] = []
        graph[edge[0]].append(edge[1])

    def visit(node, visited, stack):
        if node in stack:
            return True
        if node in visited:
            return False

        visited.add(node)
        stack.add(node)
        if node in graph:
            for neighbour in graph[node]:
                if visit(neighbour, visited, stack):
                    return True
        stack.remove(node)
        return False

    visited = set()
    stack = set()
    for node in graph:
        if visit(node, visited, stack):
            return True
    return False
```

