def shortest_subarray(nums, target):
    n = len(nums)
    pre_sum = [0] * (n + 1)
    for i in range(n):
        pre_sum[i + 1] = pre_sum[i] + nums[i]

    if pre_sum[-1] < target:
        return 0

    res = n + 1
    for i in range(1, n + 1):
        tmp_tar = pre_sum[i] - target
        if tmp_tar < 0:
            continue
        left = 0
        right = i
        while left < right:
            mid = (left + right) // 2
            if pre_sum[mid] < tmp_tar:
                left = mid + 1
            else:
                right = mid

        if pre_sum[left] >= tmp_tar:
            res = min(res, i - left)

    return res if res <= n else 0
```

