def find_target_positions(nums, target):
    def binary_search(nums, target, findFirst):
        low, high = 0, len(nums) - 1
        ans = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] > target:
                high = mid - 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                ans = mid
                if findFirst:
                    high = mid - 1
                else:
                    low = mid + 1
        return ans

    first = binary_search(nums, target, True)
    if first == -1:
        return [-1, -1]
    last = binary_search(nums, target, False)
    return [first, last]
```

