    for i in range(len(cur_word)):
        left = cur_word[:i]
        right = cur_word[i + 1:]
        for c in "abcdefghijklmnopqrstuvwxyz":
            if c != cur_word[i]:
                new_word = left + c + right
                if new_word in wordList:
                    next_words.append(new_word)
    return next_words
