def is_dag(edges):
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
    indegree = {}
    for u, v in edges:
        if v not in indegree:
            indegree[v] = 0
        indegree[v] += 1
    queue = [u for u in graph if u not in indegree]
    while queue:
        u = queue.pop(0)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    if sum(indegree.values()) > 0:
