def find_min_jumps(nums):
    if len(nums) <= 1:
        return 0
    if nums[0] == 0:
        return -1
    maxReach = nums[0]
    step = nums[0]
    jump = 1
    for i in range(1, len(nums)):
        if i == len(nums) - 1:
            return jump
        maxReach = max(maxReach, i + nums[i])
        step -= 1
        if step == 0:
            jump += 1
            if i >= maxReach:
                return -1
            step = maxReach - i
    return -1
