def min_substring(s, t):
    if not s or not t:
        return ""
    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0
    window_counts = {}
    l, r, min_length = 0, 0, float("inf")
    min_window = ""

    while r < len(s):
        character = s[r]
        if character in dict_t:
            window_counts[character] = window_counts.get(character, 0) + 1
            if window_counts[character] == dict_t[character]:
                formed += 1

        while l <= r and formed == required:
            character = s[l]
            if r - l + 1 < min_length:
                min_length = r - l + 1
                min_window = s[l : r + 1]

            if character in dict_t:
                window_counts[character] -= 1
                if window_counts[character] < dict_t[character]:
                    formed -= 1

            l += 1

        r += 1

    return min_window
```

