        visited[v] = True
        rec_stack[v] = True
        for i, x in enumerate(matrix[v]):
            if x == 1:
                if not visited[i]:
                    if dfs(i, visited, rec_stack):
                        return True
                elif rec_stack[i]:
                    return True
        rec_stack[v] = False
        return False

