class TrieNode: 
    def __init__(self): 
        self.children = {} 
        self.end = False

class Trie: 
    def __init__(self): 
        self.root = TrieNode()

    def insert(self, val): 
        node = self.root 
        for i in reversed(range(32)): 
            bit = (val >> i) & 1 
            if bit not in node.children: 
                node.children[bit] = TrieNode() 
            node = node.children[bit]

    def find_max_xor(self, val): 
        node = self.root 
        xor_val = 0
        for i in reversed(range(32)): 
            bit = (val >> i) & 1 
            if 1 - bit in node.children: 
                xor_val |= (1 << i) 
                node = node.children[1 - bit]
            else: 
                node = node.children[bit]
        return xor_val

