def can_partition(nums):
    total = sum(nums)
    if total % 2 != 0:
        return False

    target = total // 2
    seen = [0] * len(nums)
    nums.sort(reverse=True)

    def dfs(index, current_sum):
        if current_sum == target:
            return True

        for i in range(index, len(nums)):
            if not seen[i] and current_sum + nums[i] <= target:
                seen[i] = 1
                if dfs(i + 1, current_sum + nums[i]):
                    return True
                seen[i] = 0
        return False

    return dfs(0, 0)
