class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.length = 0

    def append(self, value):
        new_node = Node(value)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            self.tail = new_node
        self.length += 1

    def kth_to_last(self, k):
        slow = self.head
        fast = self.head
        for _ in range(k):
            fast = fast.next
        while fast is not None:
            slow = slow.next
            fast = fast.next
        return slow.value

def kth_to_last(k, lst):
    ll = LinkedList()
    for elem in lst:
        ll.append(elem)
    return ll.kth_to_last(k)
```

