def is_tree(edges):
    parent = {}
    rank = {}

    def make_set(u):
        parent[u] = u
        rank[u] = 0

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root1 = find(u)
        root2 = find(v)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            elif rank[root1] < rank[root2]:
                parent[root1] = root2
            else:
                parent[root2] = root1
                rank[root1] += 1

    for u, v in edges:
        make_set(u)
        make_set(v)
        if find(u) == find(v):
            return False
        union(u, v)

    return len(edges) == len(parent) - 1
```

