def count_subarrays_with_k_distinct(arr, k):
    def at_most_k_distinct(arr, k):
        start, end = 0, 0
        count = 0
        freq = {}
        while end < len(arr):
            if arr[end] not in freq:
                k -= 1
                freq[arr[end]] = 0
            freq[arr[end]] += 1
            if k >= 0:
                count += end - start + 1
            else:
                while k < 0:
                    freq[arr[start]] -= 1
                    if freq[arr[start]] == 0:
                        del freq[arr[start]]
                        k += 1
                    start += 1
                count += end - start + 1
            end += 1
        return count

    return at_most_k_distinct(arr, k) - at_most_k_distinct(arr, k-1)
