    length, rev = len(nums), []
    def combineRecursive(start, pos, tmp, n):
        if pos == n:
            rev.append(list(tmp))
            return
        for i in range(start, length + 1 - n + pos):
            tmp[pos] = nums[i]
            combineRecursive(i + 1, pos + 1, tmp, n)

    for n in range(len(nums) + 1):
