def rabin_karp_search(haystack: str, needle: str) -> int:
    if not needle or needle not in haystack:
        return -1

    base = 256
    prime = 101
    n = len(haystack)
    m = len(needle)
    h = 1
    p = 0
    t = 0

    for i in range(m-1):
        h = (h * base) % prime

    for i in range(m):
        p = (base * p + ord(needle[i])) % prime
        t = (base * t + ord(haystack[i])) % prime

    for i in range(n-m+1):
        if p == t:
            for j in range(m):
                if haystack[i+j] != needle[j]:
                    break
            else:
                return i
        if i < n-m:
            t = (base * (t - ord(haystack[i]) * h) + ord(haystack[i+m])) % prime
            if t < 0:
                t = t + prime
    return -1
```

