    i = 0
    n = len(nums)
    compressed = []

    while i<n:
        if nums[i] == 0:
            compressed.append(0)
        else:
            j = i
            cnt = 0
            while j<n and nums[j]==1:
                cnt += 1
                j += 1
            i = j
            compressed.append(cnt)
            if j<n:
                compressed.append(0)
        i += 1

    if len(compressed) == 1:
        if compressed[0] != 0:
            return compressed[0] - 1
        else:
            return 0
    else:
        ans = 0
        for i, cnt in enumerate(compressed):
            if cnt == 0:
                pre = 0 if i==0 else compressed[i-1]
                post = 0 if i==len(compressed)-1 else compressed[i+1]
                ans = max(ans, pre+post)
        return ans
```

