def min_steps(arr):
    if len(arr) == 1:
        return 0
    queue = [(0, 0)]
    visited = [False] * len(arr)
    while queue:
        pos, step = queue.pop(0)
        if pos == len(arr) - 1:
            return step
        left, right = pos - arr[pos], pos + arr[pos]
        for next_pos in range(max(0, left), min(len(arr), right) + 1):
            if not visited[next_pos]:
                visited[next_pos] = True
                queue.append((next_pos, step + 1))
    return -1
