class UnionFind(object):
    def __init__(self, n):
        self.uf = [-1 for i in range(n + 1)]
        self.sets_count = n

    def find(self, p):
        if self.uf[p] < 0:
            return p
        self.uf[p] = self.find(self.uf[p])
        return self.uf[p]

    def union(self, p, q):
        proot = self.find(p)
        qroot = self.find(q)
        if proot == qroot:
            return
        elif self.uf[proot] > self.uf[qroot]:
            self.uf[qroot] += self.uf[proot]
            self.uf[proot] = qroot
        else:
            self.uf[proot] += self.uf[qroot]
            self.uf[qroot] = proot
        self.sets_count -= 1

    def is_connected(self, p, q):
        return self.find(p) == self.find(q)

def count_connected_components(edges):
    max_node = max([max(edge) for edge in edges])
    uf = UnionFind(max_node)
    for edge in edges:
        uf.union(edge[0], edge[1])
    return uf.sets_count
