class TrieNode:
    def __init__(self):
        self.children = {}
        self.isEnd = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, num):
        node = self.root
        for i in reversed(range(32)):
            bit = (num >> i) & 1
            if bit not in node.children:
                node.children[bit] = TrieNode()
            node = node.children[bit]

    def findMaxXOR(self, query):
        node = self.root
        xor = 0
        for i in reversed(range(32)):
            bit = (query >> i) & 1
            toggle = 1 - bit
            if toggle in node.children:
                xor |= (1 << i)
                node = node.children[toggle]
            else:
                node = node.children[bit]
        return xor

