        return 0


    nrows = len(matrix)
    ncols = len(matrix[0])

    max_area = 0

    height = [0] * (ncols + 1) # array length is ncols + 1 since we have to add a '0' in the end, similar to Largest Rectangle in Histogram


    for i in range(nrows):
        stack = []
        for j in range(ncols + 1):
            if j < ncols:
                if matrix[i][j] == '1':
                    height[j] += 1

