def find_order(numCourses, prerequisites):
    graph = defaultdict(list)
    indegrees = [0]*numCourses
    for course, pre in prerequisites:
        graph[pre].append(course)
        indegrees[course] += 1
    queue = [i for i in range(numCourses) if indegrees[i] == 0]
    order = []
    while queue:
        course = queue.pop(0)
