class MaxXOR:
    def __init__(self):
        self.root = {}

    def add(self, n):
        node = self.root
        for i in reversed(range(32)):
            bit = (n >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]

    def query(self, n):
        node = self.root
        xor_sum = 0
        for i in reversed(range(32)):
            bit = (n >> i) & 1
            if 1 - bit in node:
                xor_sum |= (1 << i)
                node = node[1 - bit]
            else:
                node = node[bit]
        return xor_sum

def find_max_xor(nums):
