        return 0

    max_area = 0
    dp = [0] * len(matrix[0])
    for row in matrix:
        for i in range(len(row)):
            dp[i] = dp[i] + 1 if row[i] == 1 else 0

        stack = [-1]
        for i in range(len(dp) + 1):
            while stack[-1] != -1 and (i == len(dp) or dp[stack[-1]] >= dp[i]):
