import heapq

def minCostConnectPoints(points):
    def manhattan_distance(p1, p2):
        return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

    N = len(points)
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            edges.append((manhattan_distance(points[i], points[j]), i, j))
    edges.sort()

    parent = list(range(N))
    rank = [0]*N

    def find_parent(x):
        if parent[x] != x:
            parent[x] = find_parent(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find_parent(x)
        rootY = find_parent(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    min_cost = 0
    for cost, x, y in edges:
        if find_parent(x) != find_parent(y):
            union(x, y)
            min_cost += cost

    return min_cost
```

