def circular_array_loop(nums):
    N = len(nums)
    def nxt(x):
        return (x + nums[x]) % N
    for i in range(N):  
        if nums[i] == 0: continue  
        slow, fast = i, nxt(i)
        while nums[slow] * nums[fast] > 0 and nums[fast] * nums[nxt(fast)] > 0:
            if slow == fast:
                if slow == nxt(fast):
                    break  
                else:
                    return True
            slow = nxt(slow)
            fast = nxt(nxt(fast))

        val = nums[i]  
        while val * nums[i] > 0:
            tmp = nxt(i)
            nums[i] = 0
            i = tmp
    return False
