class Solution:
    def gcd(self,a,b):
        if a<b:
            return self.gcd(b,a)
        while b!=0:
            tmp = a%b
            a=b
            b = tmp
        return a

    def calK(self,x1,y1,x2,y2):
        if x1 == x2:
            return x1, float('inf')
        if y1 == y2:
            return float('inf'), y1

        delta_x = (x2-x1)
        delta_y = (y2-y1)
        neg = delta_x*delta_y<0

        delta_x = abs(delta_x)
        delta_y = abs(delta_y)

        gcd = self.gcd(delta_x,delta_y)

        delta_x/=gcd
        delta_y/=gcd

        if neg:
            delta_x = -delta_x
        return delta_x, delta_y

    def maxPoints(self, points) -> int:
        if len(points) == 1:
            return 1

        ans = 0
        for i in range(len(points)):
            x1,y1 = points[i]
            dic = {}
            for j in range(i+1,len(points)):
                x2,y2 = points[j]

                delta_x, delta_y = self.calK(x1,y1,x2,y2)

                if delta_x not in dic:
                    dic[delta_x] = {}
                if delta_y not in dic[delta_x]:
                    dic[delta_x][delta_y] = 0
                dic[delta_x][delta_y]+=1
                ans = max(ans,dic[delta_x][delta_y])
        return ans+1
obj = Solution()
def max_points(points):
    return obj.maxPoints(points)
