def binary_search_count(nums, target):
    def find_left(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    def find_right(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left

    left_index = find_left(nums, target)
    right_index = find_right(nums, target)

    return right_index - left_index if left_index < len(nums) and nums[left_index] == target else 0
