    n = len(nums)
    if n < 3:
        return False
    v =  bin_search(nums)

    if v == -1 or v == 0 or v == n-1:
        return False

    for i in range(v):
        if nums[i] >= nums[i+1]:
            return False

    for i in range(v, n-1):
        if nums[i] <= nums[i+1]:
            return False
    return True

def bin_search(nums):
    n = len(nums)
    if n < 3:
        return -1 
    left, right = 0, len(nums)-1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid+1]:
            left = mid + 1
        else:
            right = mid
    if left+1 != len(nums) and nums[left] > nums[left+1]:
        return left
    return -1
```

