def findShortestSubarray(arr):
    front = []

    for num in arr:
        if not front or front[-1] <= num:
            front.append(num)
        else:
            break

    tail = []
    for i in range(len(arr) - 1, -1, -1):
        if not tail or tail[-1] >= arr[i]:
            tail.append(arr[i])
