        count[s[j]] = count.get(s[j], 0) + 1

        if count[s[j]] == 1:
            count_distinct += 1

        if count_distinct == dist_count_char:
            while count[s[start]] > 1:
                if count[s[start]] > 1:
                    count[s[start]] -= 1
                start += 1

            len_window = j - start + 1
            if min_len > len_window:
                min_len = len_window
                start_index = start

