def partition(s):
    def dfs(start):
        if start >= len(s): return [[]]
        result = []
        for i in range(start, len(s)):
            if s[start:i + 1] == s[start:i + 1][::-1]:
                ret = dfs(i + 1)
                for l in ret:
                    result.append([s[start:i + 1]] + l)
        return result

    return dfs(0)

