def missing_element(nums, k):
    if not nums or k == 0:
        return 0
    diff = nums[-1] - nums[0] + 1
    missing = diff - len(nums)
    if missing < k:
        return nums[-1] + k - missing
    l, r = 0, len(nums) - 1
    while l + 1 < r:
        mid = (l + r) // 2
        missing = nums[mid] - nums[l] - (mid - l)
        if missing < k:
            l = mid
            k -= missing
        else:
            r = mid
    return nums[l] + k
