def decodeString(s: str) -> str:
    stack = []
    for val in s:
        if val != "]":
            stack.append(val)
        else:
            substr = ""
            while stack[-1] != "[":
                substr = stack.pop() + substr  # get the substring
            stack.pop()  # pop the [
            num = ""
            while stack and stack[-1].isdigit():  # get the number
                num = stack.pop() + num
            stack.append(int(num) * substr)
    return "".join(stack)
