    if len(s) < 3:
        return len(s)

    left = 0
    right = 0
    max_length = 0
    char_map = {}
    distinct_count = 0

    while right < len(s):
        if s[right] not in char_map:
            char_map[s[right]] = 0
            distinct_count += 1
        char_map[s[right]] += 1

        while distinct_count > 2:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
                distinct_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length
