def count_unique_pairs(nums: List[int], target: int) -> int:
    nums.sort()
    n = len(nums)
    l, r = 0, n-1
    pairs = set()
    while l < r:
        if nums[l] + nums[r] < target:
            l += 1
        elif nums[l] + nums[r] > target:
            r -= 1
        else:
