def eval_postfix(expression):
    operations = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: int(float(x) / float(y))
    }

    stack = []

    for ele in expression:
        if ele in operations:
            temp1 = stack.pop()
            temp2 = stack.pop()
            stack.append(operations[ele](temp2, temp1))
        else:
            stack.append(int(ele))
    return stack[0]
