def count_unique_pairs(arr, k):
    if k < 0:
        return 0
    pairs = 0
    elements = {}
    for num in arr:
        if num in elements:
            elements[num] += 1
        else:
            elements[num] = 1
    for num in elements:
        if k > 0 and num + k in elements:
            pairs += elements[num] * elements[num + k]
        elif k == 0 and elements[num] > 1:
            pairs += elements[num] * (elements[num] - 1) // 2
    return pairs
