def is_pattern_match(word, pattern):
  p = 0  # pointer for pattern
  w = 0  # pointer for word
  stack = []
  while p < len(pattern) and w < len(word):
    if pattern[p] == '*':
      if not stack or stack[-1] != pattern[p-1]:
        stack.append((pattern[p-1], 0))
      else:
        stack[-1] = (pattern[p-1], stack[-1][1] + 1)
      p+=1
    elif pattern[p] == '.':
      w += 1
      p += 1
    elif pattern[p] == word[w]:
      w += 1
      p += 1
    else:
      if stack:
        p = stack[-1][0]
        w = w - stack[-1][1]
        stack.pop()
      else:
        return False
  while p < len(pattern):
    if pattern[p] != '*':
      return False
    p += 1
  return w == len(word)
```

