def zigzag_conversion(s, numRows):
    if numRows == 1:
        return s

    result = ''

    for firstLetterIndex in range(numRows):
        upSkip, downSkip = numToSkip(firstLetterIndex, numRows)
        goingDown = True
        doNotAppend = False
        cursor = firstLetterIndex
        while cursor < len(s):
            if not doNotAppend:
                result += s[cursor]
            doNotAppend = False
            if goingDown:
                goingDown = False
                if downSkip <= 0:
                    doNotAppend = True
                    continue
                cursor += downSkip
            else:
                goingDown = True
                if upSkip <= 0:
                    doNotAppend = True
                    continue
                cursor += upSkip
    return result

def numToSkip(rowNum, numRows):
    down = (numRows - rowNum - 1) * 2 - 1
    up = (rowNum) * 2 - 1
    return up + 1, down + 1
```

