def shortest_distance_bfs(graph, start, end):
    queue = deque([(start, 0)])
    visited = set()

    while queue:
        current, distance = queue.popleft()
        if current == end:
            return distance
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append((neighbor, distance + 1))
    return -1
