from collections import deque

def shortest_distance(grid):
    m, n = len(grid), len(grid[0])
    total_buildings = sum(cell == 1 for row in grid for cell in row)

    distances = [[0] * n for _ in range(m)]
    reachable = [[0] * n for _ in range(m)]

    def bfs(x, y):
        queue = deque([(x, y)])
        visited = set([(x, y)])
        level = 0

        while queue:
            level += 1
            for _ in range(len(queue)):
                x, y = queue.popleft()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0 and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        distances[nx][ny] += level
                        reachable[nx][ny] += 1
                        queue.append((nx, ny))

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                bfs(i, j)

    min_distance = float('inf')
    for i in range(m):
        for j in range(n):
            if reachable[i][j] == total_buildings:
                min_distance = min(min_distance, distances[i][j])

    return min_distance if min_distance != float('inf') else -1
```

