def closest_element(arr, num):
    arr.sort()
    pos = binary_search(arr, num)
    if pos == 0:
        return abs(num - arr[0])
    if pos == len(arr):
        return abs(num - arr[-1])
    before = arr[pos - 1]
    after = arr[pos]
    return min(abs(num - before), abs(num - after))

def binary_search(arr, num):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < num:
            left = mid + 1
        elif arr[mid] > num:
            right = mid - 1
        else:
            return mid
    return left
```

